// Generated by Cypress Author on 2026-11-03 for IMP-06.07.
// The same persisted Docker attempts, TEST hint and evaluated signal cross roles.
import type { Session } from '@supabase/supabase-js';
import type { AuditExportMetadata, AuditEvent } from '@alunza/contracts';
import { pressEnterInChrome, pressKeyInChrome } from './keyboard';

type Scope = {
  organizationId: string;
  classroomId: string;
  otherClassId: string;
  studentId: string;
  emptyStudentId: string;
  otherOrganizationId: string;
  foreignClassId: string;
  foreignStudentId: string;
  foreignExerciseId: string;
  teacherId: string;
  adminId: string;
  foreignAdminId: string;
  exerciseId: string;
  versionId: string;
  activityId: string;
  assignmentId: string;
  attemptId: string;
  attemptIds: string[];
  hintId: string;
  signalId: string;
  sourceId: string;
  ruleId: string;
  from: string;
  asOf: string;
};
type Facts = {
  audits: Record<string, number>;
  reviews: { signalId: string; reviewedBy: string; reviewedAt: string }[];
  exports: { exportId: string; state: string; sha256: string }[];
  deliveries: { state: string }[];
  exercise: {
    ownerId: string;
    visibility: string;
    revision: number;
    currentVersionId: string;
    archived: boolean;
  };
};
type Snapshot = {
  history: Record<string, { count: number; digest: string }>;
  operational: Facts;
};
type Response<T> = { status: number; data: T; error?: { code: string } };
const el = (name: string) => `[data-cy="${name}"]`;
const snapshot = (c: Scope) =>
  cy.task<Snapshot>('governance-phase:snapshot', c, { log: false });
const facts = (c: Scope) =>
  cy.task<Facts>('governance-phase:facts', c, { log: false });
function request<T>(
  c: Scope,
  path: string,
  options: Record<string, unknown> = {},
) {
  return cy.task<Response<T>>(
    'governance-phase:request',
    { ...c, path, options },
    { log: false, timeout: 60000 },
  );
}
function visit(
  c: Scope,
  role: 'STUDENT' | 'TEACHER' | 'ADMIN',
  path: string,
  beforeLoad?: (window: Cypress.AUTWindow) => void,
) {
  cy.task<Session>('identity:login', role, { log: false }).then((session) => {
    cy.visit(path, {
      onBeforeLoad(window) {
        window.localStorage.setItem(
          'alunza.auth.127.0.0.1:18421',
          JSON.stringify(session),
        );
        beforeLoad?.(window);
      },
    });
  });
}
function detail(c: Scope) {
  visit(
    c,
    'TEACHER',
    `/clases/${c.classroomId}/estudiantes/${c.studentId}?asOf=${encodeURIComponent(c.asOf)}`,
  );
  cy.get(el('student-detail-ready')).should('be.visible');
  cy.get(el('student-detail-attempt-row')).should('have.length', 3);
  cy.get('body').should('not.contain.text', 'DASHBOARD_HIDDEN_SENTINEL');
}
function openReview(c: Scope) {
  cy.get(`${el('student-detail-signal-row')}[data-signal-id="${c.signalId}"]`)
    .find(el('student-detail-open-signal'))
    .click();
  cy.get(el('student-detail-signal-attempt')).should('have.length', 3);
  cy.get(el('signal-review-open')).click();
  cy.get(el('signal-review-confirmation')).should('be.visible');
}
function bank(c: Scope, beforeLoad?: (window: Cypress.AUTWindow) => void) {
  visit(
    c,
    'ADMIN',
    `/administracion/organizaciones/${c.organizationId}/banco`,
    beforeLoad,
  );
  cy.get(`${el('exercise-bank-row')}[data-exercise-id="${c.exerciseId}"]`)
    .contains('button', 'Ver detalle')
    .click();
  cy.get('[data-testid="bank-detail-ready"]').should('be.visible');
}
function chooseGovernance() {
  cy.get(el('bank-governance-open')).click();
  cy.get(el('bank-visibility')).select('ORGANIZATION');
  cy.get(el('bank-governance-review')).click();
}
function audit(c: Scope) {
  visit(
    c,
    'ADMIN',
    `/administracion/organizaciones/${c.organizationId}/auditoria`,
  );
  cy.get('[data-testid="audit-list-ready"]').should('be.visible');
}
function exportCsv(c: Scope, alias: string) {
  cy.intercept({
    method: 'POST',
    pathname: `/api/v1/organizations/${c.organizationId}/audit-exports`,
    times: 1,
  }).as(alias);
  cy.get(el('audit-export-generate')).should('be.enabled').click();
  return cy.wait(`@${alias}`).then(({ response }) => {
    expect(response!.statusCode).to.equal(201);
    const metadata = response!.body.data as AuditExportMetadata;
    expect(metadata.organizationId).to.equal(c.organizationId);
    cy.get(el('audit-export-ready')).should(
      'have.attr',
      'data-export-id',
      metadata.exportId,
    );
    return cy.wrap(metadata, { log: false });
  });
}
function download(c: Scope, metadata: AuditExportMetadata) {
  cy.get(el('audit-export-download')).click();
  cy.contains(
    'CSV íntegro verificado y enviado al navegador para descarga.',
  ).should('be.visible');
  cy.readFile(
    `${Cypress.config('downloadsFolder')}/${metadata.fileName}`,
    null,
    { log: false },
  ).should('exist');
  return cy.task<{ rows: string[][]; rowCount: number; sha256: string }>(
    'governance-phase:readDownload',
    {
      ...c,
      exportId: metadata.exportId,
      fileName: metadata.fileName,
      kind: 'csv',
    },
    { log: false },
  );
}
function reviewed(c: Scope) {
  return request(c, `/signals/${c.signalId}/review`, {
    method: 'PUT',
    body: {},
  })
    .its('status')
    .should('equal', 200);
}

function reviewJourney(c: Scope, before: Snapshot) {
  detail(c);
  openReview(c);
  cy.get(el('signal-review-cancel')).click();
  cy.get(el('signal-review-open')).should('be.focused');
  snapshot(c).then((after) => expect(after).to.deep.equal(before));
  cy.get(el('signal-review-open')).click();
  cy.get(el('signal-review-confirm')).dblclick();
  cy.get(el('signal-review-confirmed')).should('contain.text', 'Responsable:');
  cy.location('search').should('contain', encodeURIComponent(c.asOf));
  snapshot(c).then((after) => {
    expect(after.history).to.deep.equal(before.history);
    expect(after.operational.reviews).to.have.length(1);
    expect(after.operational.reviews[0]!.reviewedBy).to.equal(c.teacherId);
    expect(after.operational.audits.SIGNAL_REVIEWED).to.equal(1);
    reviewed(c);
    snapshot(c).then((again) => expect(again).to.deep.equal(after));
  });
  request<{ signal: { state: string } }>(
    c,
    '/classes/' +
      c.classroomId +
      '/signals/' +
      c.signalId +
      '?asOf=' +
      encodeURIComponent(c.asOf),
  )
    .its('data.signal.state')
    .should('equal', 'ACTIVE');
  cy.get(el('signal-review-present')).click();
  cy.location('search').should('not.contain', encodeURIComponent(c.asOf));
  request<{ signal: { state: string } }>(
    c,
    '/classes/' + c.classroomId + '/signals/' + c.signalId,
  )
    .its('data.signal.state')
    .should('equal', 'REVIEWED');
}
function keyboardReview(c: Scope) {
  detail(c);
  for (const [name, width, height] of [
    ['desktop', 1440, 900],
    ['tablet', 768, 1024],
    ['mobile', 390, 844],
  ] as const) {
    cy.viewport(width, height);
    const trigger =
      el('student-detail-signal-row') +
      '[data-signal-id="' +
      c.signalId +
      '"] ' +
      el('student-detail-open-signal');
    cy.get(trigger).focus();
    pressEnterInChrome();
    cy.get(el('signal-review-open')).focus();
    pressEnterInChrome();
    cy.get(el('signal-review-confirm')).should('be.focused');
    pressKeyInChrome('Tab');
    cy.get(el('signal-review-cancel')).should('be.focused');
    cy.document().should((d) =>
      expect(d.documentElement.scrollWidth).to.be.at.most(
        d.documentElement.clientWidth + 1,
      ),
    );
    cy.screenshot('imp06-governance-phase-' + name, {
      capture: 'viewport',
      overwrite: true,
    });
    pressKeyInChrome('Escape');
    cy.get(el('signal-review-open')).should('be.focused');
    pressKeyInChrome('Escape');
    cy.get(trigger).should('be.focused');
  }
}
function auditTuple(e: AuditEvent) {
  return [
    e.eventId,
    e.occurredAt,
    e.actorId ?? '',
    e.action,
    e.entityType,
    e.entityId ?? '',
    e.organizationId,
    e.outcome,
  ];
}
function verifyQuiescentCsv(c: Scope) {
  audit(c);
  cy.get('[data-testid="audit-list-ready"]')
    .invoke('attr', 'data-cut')
    .then((asOf) => {
      expect(asOf).to.be.a('string');
      cy.task<AuditEvent[]>(
        'governance-phase:auditRows',
        { ...c, asOf },
        { log: false },
      ).then((events) => {
        expect(
          events.some(
            (e) => e.action === 'SIGNAL_REVIEWED' && e.entityId === c.signalId,
          ),
        ).to.equal(true);
        for (const action of [
          'exercise.governance.updated',
          'exercise.version.created',
          'exercise.archived',
        ])
          expect(
            events.some(
              (e) => e.action === action && e.entityId === c.exerciseId,
            ),
          ).to.equal(true);
        cy.get(el('audit-row')).should('have.length', events.length);
        exportCsv(c, 'phaseGovernanceCsv').then((metadata) => {
          expect(metadata.filters.asOf).to.equal(asOf);
          download(c, metadata).then((csv) =>
            expect(csv.rows).to.deep.equal(events.map(auditTuple)),
          );
          cy.get(el('audit-export-metadata')).click();
          cy.contains(
            'Metadatos verificados y enviados al navegador para descarga.',
          ).should('be.visible');
          const fileName = metadata.fileName.replace(/\.csv$/, '.json');
          cy.readFile(Cypress.config('downloadsFolder') + '/' + fileName, {
            log: false,
          }).should('deep.equal', metadata);
          facts(c).then((f) => {
            expect(f.audits.AUDIT_EXPORT_GENERATED).to.equal(1);
            expect(f.audits.AUDIT_EXPORT_DOWNLOADED).to.equal(1);
          });
        });
      });
    });
}

describe('IMP-06.07 · Gobierno integrado con la misma evidencia', () => {
  beforeEach(function () {
    cy.task<Scope>(
      'governance-phase:prepare',
      { browserHelp: this.currentTest?.title.includes('PHASE-01') },
      { log: false, timeout: 240000 },
    ).as('scope');
  });

  it('IMP06-PHASE-01 · Entregar ayuda, abrir detalle y revisar señal → conserva la evidencia entre roles y cortes', () => {
    cy.get<Scope>('@scope').then((c) => {
      visit(
        c,
        'STUDENT',
        '/actividades/' + c.activityId + '/ejercicios/' + c.assignmentId,
      );
      // Entering the browser revalidates access and remounts the history.
      // Focus the editor first, then wait for its authorization guard again.
      cy.get(el('student-code')).should('not.have.attr', 'readonly');
      cy.get(el('student-code')).click();
      cy.get(el('student-code')).should('not.have.attr', 'readonly');
      cy.get(el('attempt-history-row')).should('have.length', 3);
      cy.intercept({
        method: 'GET',
        pathname: '/api/v1/attempts/' + c.attemptId,
        times: 1,
      }).as('integratedStudentAttempt');
      cy.contains('button', 'Ver intento #1').click();
      cy.wait('@integratedStudentAttempt')
        .its('response.statusCode')
        .should('equal', 200);
      cy.get(el('attempt-help')).should('be.visible');
      cy.get(el('request-hint')).should('be.enabled').click();
      cy.get(el('open-prepared-help'), { timeout: 45000 })
        .should('be.visible')
        .click();
      cy.get(el('help-detail')).should('be.visible');
      cy.get(el('help-hint')).should('be.visible');
      cy.get(el('help-reference')).should(
        'contain.text',
        'Fuente integrada IMP-06',
      );
      cy.get(el('request-hint')).should('contain.text', 'Pedir pista 2 de 3');
      cy.task<Scope>('governance-phase:complete', c, { log: false }).then(
        (complete) => {
          snapshot(complete).then((before) => {
            expect(before.history.attempts!.count).to.equal(3);
            visit(
              complete,
              'TEACHER',
              '/clases/' +
                complete.classroomId +
                '/tablero?asOf=' +
                encodeURIComponent(complete.asOf),
            );
            cy.get(
              el('dashboard-open-student-detail') +
                '[href*="/estudiantes/' +
                complete.studentId +
                '?"]',
            ).click();
            cy.get(el('student-detail-ready')).should('be.visible');
            cy.get(el('student-detail-attempt-row')).should('have.length', 3);
            cy.get(
              el('student-detail-attempt-row') +
                '[data-attempt-id="' +
                complete.attemptId +
                '"]',
            )
              .find(el('student-detail-open-attempt'))
              .click();
            cy.get(el('student-detail-attempt'))
              .contains('summary', 'Código enviado y versiones')
              .click();
            cy.get(el('attempt-source')).should(
              'have.text',
              'module.exports.solve=()=>0;',
            );
            cy.get(el('attempt-diagnosis')).should(
              'contain.text',
              'FAILED_TEST',
            );
            cy.get(
              el('student-detail-feedback-row') +
                '[data-feedback-id="' +
                complete.hintId +
                '"]',
            )
              .find(el('student-detail-open-feedback'))
              .click();
            cy.get(el('student-detail-reference')).should(
              'contain.text',
              'Fuente integrada IMP-06',
            );
            cy.get('body').should(
              'not.contain.text',
              'DASHBOARD_HIDDEN_SENTINEL',
            );
            snapshot(complete).then((after) =>
              expect(after).to.deep.equal(before),
            );
            keyboardReview(complete);
            snapshot(complete).then((after) =>
              expect(after).to.deep.equal(before),
            );
            reviewJourney(complete, before);
          });
        },
      );
    });
  });

  it('IMP06-PHASE-02 · Gobernar, versionar, archivar y exportar → conserva historia y un CSV del mismo corte', () => {
    cy.get<Scope>('@scope').then((c) =>
      snapshot(c).then((before) => {
        reviewed(c);
        bank(c);
        chooseGovernance();
        cy.get(el('bank-governance-cancel')).click();
        facts(c).then((f) => {
          expect(f.exercise).to.deep.equal(before.operational.exercise);
          expect(f.audits['exercise.governance.updated'] ?? 0).to.equal(0);
        });
        chooseGovernance();
        cy.intercept({
          method: 'PATCH',
          pathname: '/api/v1/exercises/' + c.exerciseId + '/governance',
          times: 1,
        }).as('integratedGovernance');
        cy.intercept({
          method: 'GET',
          pathname: '/api/v1/exercises/' + c.exerciseId + '/governance',
          times: 1,
        }).as('integratedGovernanceRefresh');
        cy.get(el('bank-governance-confirm')).click();
        cy.wait('@integratedGovernance')
          .its('response.statusCode')
          .should('equal', 200);
        cy.get(el('bank-governance-form')).should('not.exist');
        cy.wait('@integratedGovernanceRefresh')
          .its('response.body.data.visibility')
          .should('equal', 'ORGANIZATION');
        cy.get('[data-testid="bank-detail-ready"]').should(
          'contain.text',
          'Organización',
        );
        cy.get(el('bank-version-open')).click();
        cy.get('[name="title"]')
          .clear()
          .type('Versión integrada conservando historia');
        cy.intercept({
          method: 'POST',
          pathname: '/api/v1/exercises/' + c.exerciseId + '/versions',
          times: 1,
        }).as('integratedVersion');
        cy.intercept({
          method: 'GET',
          pathname: '/api/v1/exercises/' + c.exerciseId + '/governance',
          times: 1,
        }).as('integratedVersionRefresh');
        cy.get(el('bank-version-submit')).click();
        cy.wait('@integratedVersion')
          .its('response.statusCode')
          .should('equal', 201);
        cy.get(el('bank-version-form')).should('not.exist');
        // Closing the version form precedes its asynchronous detail refresh.
        // Archive only after the new revision has reached the visible detail.
        cy.wait('@integratedVersionRefresh')
          .its('response.body.data.currentVersion.version')
          .should('equal', 2);
        cy.get('[data-testid="bank-detail-ready"]')
          .should('contain.text', 'Versión integrada conservando historia')
          .and('contain.text', '2 de 2 versiones');
        cy.get(el('bank-archive-review')).click();
        cy.get('[name="reason"]').type(
          'Retiro administrativo con historia preservada',
        );
        cy.intercept({
          method: 'POST',
          pathname: '/api/v1/exercises/' + c.exerciseId + '/archive',
          times: 1,
        }).as('integratedArchive');
        cy.get(el('bank-archive-confirm')).click();
        cy.wait('@integratedArchive')
          .its('response.statusCode')
          .should('equal', 200);
        cy.get('[data-testid="bank-detail-ready"]').should(
          'contain.text',
          'Archivado',
        );
        snapshot(c).then((after) => {
          expect(after.history).to.deep.equal(before.history);
          expect(after.operational.exercise.currentVersionId).not.to.equal(
            c.versionId,
          );
          for (const action of [
            'exercise.governance.updated',
            'exercise.version.created',
            'exercise.archived',
          ])
            expect(after.operational.audits[action]).to.equal(1);
        });
        detail(c);
        cy.get(
          el('student-detail-attempt-row') +
            '[data-attempt-id="' +
            c.attemptId +
            '"]',
        )
          .find(el('student-detail-open-attempt'))
          .click();
        cy.get(
          el('student-detail-feedback-row') +
            '[data-feedback-id="' +
            c.hintId +
            '"]',
        ).should('exist');
        verifyQuiescentCsv(c);
        snapshot(c).then((after) =>
          expect(after.history).to.deep.equal(before.history),
        );
      }),
    );
  });

  it('IMP06-PHASE-03 · Corregir filtros y políticas inválidas y consultar vacíos → no crea evidencia ni CSV parcial', () => {
    cy.get<Scope>('@scope').then((c) =>
      snapshot(c).then((before) => {
        visit(
          c,
          'TEACHER',
          '/clases/' +
            c.classroomId +
            '/estudiantes/' +
            c.studentId +
            '?from=invalid',
        );
        cy.get('[role="alert"]').should('be.visible');
        cy.get(el('student-detail-attempt-row')).should('not.exist');
        visit(
          c,
          'TEACHER',
          '/clases/' +
            c.classroomId +
            '/estudiantes/' +
            c.emptyStudentId +
            '?asOf=' +
            encodeURIComponent(c.asOf),
        );
        cy.get(el('student-detail-ready')).should('be.visible');
        cy.contains(
          'Este estudiante no tiene intentos confirmados en esta clase hasta el corte.',
        ).should('be.visible');
        bank(c);
        let submittedVersions = 0;
        cy.intercept(
          'POST',
          '**/api/v1/exercises/' + c.exerciseId + '/versions',
          (req) => {
            submittedVersions++;
            req.continue();
          },
        );
        cy.get(el('bank-version-open')).click();
        cy.get('[name="tests.0.visibility"]').select('hidden');
        cy.get(el('bank-version-submit')).click();
        cy.get('[role="dialog"] [role="alert"]').should('be.visible');
        cy.then(() => expect(submittedVersions).to.equal(0));
        cy.get(el('bank-version-form')).contains('button', 'Cancelar').click();
        request(c, '/exercises/' + c.exerciseId + '/governance', {
          actor: 'admin',
          method: 'PATCH',
          revision: before.operational.exercise.revision,
          body: { visibility: 'PUBLIC' },
        })
          .its('status')
          .should('equal', 422);
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        audit(c);
        cy.get('[name="actorId"]').type('actor-invalido');
        cy.get(el('audit-filters'))
          .contains('button', 'Aplicar filtros')
          .click();
        cy.get('[name="actorId"]').should('have.attr', 'aria-invalid', 'true');
        cy.get(el('audit-export-generate')).should('be.disabled');
        cy.get('[name="actorId"]').clear();
        cy.get('[name="from"]').type('2099-01-01T12:00');
        cy.get(el('audit-filters'))
          .contains('button', 'Aplicar filtros')
          .click();
        cy.get('[name="from"]').should('have.attr', 'aria-invalid', 'true');
        cy.get(el('audit-export-generate')).should('be.disabled');
        cy.get('[name="from"]').clear();
        cy.get('[name="action"]').type('NO_SUCH_OPERATION_IMP0607');
        cy.get(el('audit-filters'))
          .contains('button', 'Aplicar filtros')
          .click();
        cy.contains('No hay registros para estos filtros.').should(
          'be.visible',
        );
        cy.get(el('audit-row')).should('not.exist');
        exportCsv(c, 'emptyIntegratedCsv').then((metadata) => {
          expect(metadata.rowCount).to.equal(0);
          download(c, metadata).then((csv) =>
            expect(csv.rows).to.deep.equal([]),
          );
        });
        snapshot(c).then((after) => {
          expect(after.history).to.deep.equal(before.history);
          expect(after.operational.exercise).to.deep.equal(
            before.operational.exercise,
          );
          expect(after.operational.reviews).to.have.length(0);
          expect(
            after.operational.audits['exercise.version.created'] ?? 0,
          ).to.equal(0);
        });
      }),
    );
  });

  it('IMP06-PHASE-04 · Cambiar rol, clase u organización y revocar antes de confirmar → retira datos y rechaza escrituras', () => {
    cy.get<Scope>('@scope').then((c) =>
      snapshot(c).then((before) => {
        for (const role of ['ADMIN', 'STUDENT'] as const) {
          visit(
            c,
            role,
            '/clases/' +
              c.classroomId +
              '/estudiantes/' +
              c.studentId +
              '?asOf=' +
              encodeURIComponent(c.asOf),
          );
          cy.get('[role="alert"]').should('be.visible');
          cy.get(el('student-detail')).should('not.exist');
        }
        for (const [classId, studentId] of [
          [c.otherClassId, c.studentId],
          [c.foreignClassId, c.foreignStudentId],
        ]) {
          visit(
            c,
            'TEACHER',
            '/clases/' +
              classId +
              '/estudiantes/' +
              studentId +
              '?asOf=' +
              encodeURIComponent(c.asOf),
          );
          cy.get('[role="alert"]').should('be.visible');
          cy.get(el('student-detail-attempt-row')).should('not.exist');
        }
        for (const role of ['TEACHER', 'STUDENT'] as const) {
          visit(
            c,
            role,
            '/administracion/organizaciones/' + c.organizationId + '/banco',
          );
          cy.get('[role="alert"]').should('be.visible');
          cy.get(el('exercise-bank-row')).should('not.exist');
          visit(
            c,
            role,
            '/administracion/organizaciones/' + c.organizationId + '/auditoria',
          );
          cy.get('[role="alert"]').should('be.visible');
          cy.get(el('audit-row')).should('not.exist');
        }
        visit(
          c,
          'ADMIN',
          '/administracion/organizaciones/' +
            c.otherOrganizationId +
            '/auditoria',
        );
        cy.get('[role="alert"]').should('be.visible');
        cy.get(el('audit-row')).should('not.exist');
        request(c, '/exercises/' + c.foreignExerciseId + '/governance', {
          actor: 'admin',
          method: 'PATCH',
          revision: 1,
          body: { visibility: 'ORGANIZATION' },
        })
          .its('status')
          .should('equal', 404);
        request(c, '/exercises/' + c.exerciseId + '/governance', {
          actor: 'admin',
          method: 'PATCH',
          revision: before.operational.exercise.revision,
          body: {
            visibility: 'ORGANIZATION',
            organizationId: c.otherOrganizationId,
          },
        })
          .its('status')
          .should('equal', 422);
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        detail(c);
        openReview(c);
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'teacher' },
          { log: false },
        );
        cy.get(el('signal-review-confirm')).click();
        cy.get(el('student-detail')).should('not.exist');
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'teacher', restore: true },
          { log: false },
        );
        bank(c);
        chooseGovernance();
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'admin' },
          { log: false },
        );
        cy.get(el('bank-governance-confirm')).click();
        cy.get('[role="alert"]').should('be.visible');
        cy.get('[data-testid="bank-detail-ready"]').should('not.exist');
        snapshot(c).then((after) => expect(after).to.deep.equal(before));
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'admin', restore: true },
          { log: false },
        );
      }),
    );
  });

  it('IMP06-PHASE-05 · Confirmar solicitudes concurrentes y repetir revisión → un autor original y conflicto de gobierno', () => {
    cy.get<Scope>('@scope').then((c) =>
      snapshot(c).then((before) => {
        request(c, '/signals/invalid/review', { method: 'PUT', body: {} })
          .its('status')
          .should('equal', 422);
        detail(c);
        openReview(c);
        cy.task<{
          observed: number;
          responses: Response<unknown>[];
          after: Facts;
        }>(
          'governance-phase:concurrency',
          { ...c, kind: 'review' },
          { log: false, timeout: 60000 },
        ).then((race) => {
          expect(race.observed).to.be.at.least(2);
          expect(race.responses.map((r) => r.status).sort()).to.deep.equal([
            200, 200,
          ]);
          expect(race.after.reviews).to.have.length(1);
          expect(race.after.reviews[0]!.reviewedBy).to.equal(c.teacherId);
          expect(race.after.audits.SIGNAL_REVIEWED).to.equal(1);
          cy.get(el('signal-review-confirm')).click();
          cy.get(el('signal-review-confirmed')).should(
            'have.attr',
            'data-reviewed-at',
            race.after.reviews[0]!.reviewedAt,
          );
          facts(c).then((after) => expect(after).to.deep.equal(race.after));
        });
        bank(c);
        chooseGovernance();
        cy.task<{
          observed: number;
          responses: Response<unknown>[];
          before: Facts;
          after: Facts;
        }>(
          'governance-phase:concurrency',
          { ...c, kind: 'governance' },
          { log: false, timeout: 60000 },
        ).then((race) => {
          expect(race.observed).to.be.at.least(2);
          expect(race.responses.map((r) => r.status).sort()).to.deep.equal([
            200, 412,
          ]);
          expect(race.after.exercise.revision).to.equal(
            race.before.exercise.revision + 1,
          );
          expect(race.after.exercise.ownerId).to.equal(c.adminId);
          expect(race.after.exercise.visibility).to.equal('ORGANIZATION');
          expect(race.after.audits['exercise.governance.updated']).to.equal(1);
          cy.intercept({
            method: 'PATCH',
            pathname: '/api/v1/exercises/' + c.exerciseId + '/governance',
            times: 1,
          }).as('phaseStaleGovernance');
          cy.get(el('bank-governance-confirm')).click();
          cy.wait('@phaseStaleGovernance')
            .its('response.statusCode')
            .should('equal', 412);
          cy.get('[role="dialog"] [role="alert"]').should('be.visible');
          cy.contains('button', 'Cargar datos actuales').click();
          cy.get(el('bank-governance-form')).should(
            'contain.text',
            'Datos actuales cargados',
          );
          cy.get(el('bank-visibility')).should('have.value', 'ORGANIZATION');
          facts(c).then((after) => expect(after).to.deep.equal(race.after));
        });
        snapshot(c).then((after) =>
          expect(after.history).to.deep.equal(before.history),
        );
      }),
    );
  });

  it('IMP06-PHASE-06 · Recuperar CSV después del commit y cambiar el gobierno → conserva bytes y exige solicitante y acceso vigente', () => {
    cy.get<Scope>('@scope').then((c) => {
      let lost = false,
        blobs = 0;
      reviewed(c);
      visit(
        c,
        'ADMIN',
        '/administracion/organizaciones/' + c.organizationId + '/auditoria',
        (window) => {
          const fetch = window.fetch.bind(window),
            create = window.URL.createObjectURL.bind(window.URL);
          window.URL.createObjectURL = (blob) => {
            blobs++;
            return create(blob);
          };
          window.fetch = (input, init) =>
            fetch(input, init).then((response) => {
              if (
                !lost &&
                init?.method === 'POST' &&
                String(input).endsWith('/audit-exports') &&
                response.ok
              ) {
                lost = true;
                throw new TypeError('Explicit TEST response lost after commit');
              }
              return response;
            });
        },
      );
      cy.get('[data-testid="audit-list-ready"]').should('be.visible');
      cy.intercept(
        'POST',
        '**/organizations/' + c.organizationId + '/audit-exports',
      ).as('recoverPhaseCsv');
      cy.get(el('audit-export-generate')).click();
      cy.wait('@recoverPhaseCsv').then(({ request: original, response }) => {
        expect(response!.statusCode).to.equal(201);
        const metadata = response!.body.data as AuditExportMetadata;
        cy.get(el('audit-export-recover')).should('be.enabled').click();
        cy.wait('@recoverPhaseCsv').then(
          ({ request: replay, response: recovered }) => {
            expect(replay.headers['idempotency-key']).to.equal(
              original.headers['idempotency-key'],
            );
            expect(replay.body).to.deep.equal(original.body);
            expect(recovered!.body.data).to.deep.equal(metadata);
          },
        );
        cy.get(el('audit-export-ready')).should(
          'have.attr',
          'data-export-id',
          metadata.exportId,
        );
        facts(c)
          .then((f) =>
            request(c, '/exercises/' + c.exerciseId + '/governance', {
              actor: 'admin',
              method: 'PATCH',
              revision: f.exercise.revision,
              body: { visibility: 'ORGANIZATION' },
            }),
          )
          .its('status')
          .should('equal', 200);
        request<AuditExportMetadata>(
          c,
          '/organizations/' +
            c.organizationId +
            '/audit-exports/' +
            metadata.exportId,
          { actor: 'admin' },
        )
          .its('data')
          .should('deep.equal', metadata);
        download(c, metadata).then((csv) => {
          expect(csv.sha256).to.equal(metadata.sha256);
          expect(
            csv.rows.some((row) => row[3] === 'exercise.governance.updated'),
          ).to.equal(false);
          expect(
            csv.rows.some(
              (row) => row[3] === 'SIGNAL_REVIEWED' && row[5] === c.signalId,
            ),
          ).to.equal(true);
        });
        facts(c).then((f) =>
          expect(f.audits['exercise.governance.updated']).to.equal(1),
        );
        for (const suffix of ['', '/content'])
          request(
            c,
            '/organizations/' +
              c.organizationId +
              '/audit-exports/' +
              metadata.exportId +
              suffix,
            { actor: 'foreignAdmin', binary: suffix !== '' },
          )
            .its('status')
            .should('equal', 404);
        cy.then(() => {
          expect(lost).to.equal(true);
          expect(blobs).to.equal(1);
        });
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'admin' },
          { log: false },
        );
        cy.get(el('audit-export-download')).click();
        cy.get(el('audit-export')).should('not.exist');
        cy.then(() => expect(blobs).to.equal(1));
        facts(c).then((f) => {
          expect(f.exports).to.have.length(1);
          expect(f.audits.AUDIT_EXPORT_GENERATED).to.equal(1);
          expect(f.audits.AUDIT_EXPORT_DOWNLOADED).to.equal(1);
          expect(f.deliveries).to.have.length(1);
        });
        cy.task(
          'governance-phase:revoke',
          { ...c, actor: 'admin', restore: true },
          { log: false },
        );
      });
    });
  });
});
